"""Render ``docs/DATA_CATALOGUE.md`` from ``data/processed/data_sources.csv`` (which comes from the download manifest)."""
from __future__ import annotations

import pandas as pd

from src.utils.paths import DOCS_DIR, PROCESSED_DIR


def build_markdown() -> str:
    ds = pd.read_csv(PROCESSED_DIR / "data_sources.csv", keep_default_na=False)
    lines = ["# Data catalogue", "",
             "Every dataset used by HomeScope Ireland. Generated by `python -m src.data_collection.catalogue` from the download manifest "
             "(`data/raw/MANIFEST.json`). Raw files are preserved unmodified; SHA-256 checksums are in the manifest.", "",
             "| Dataset | Title | Publisher | Licence | Published / updated | Reference period | Granularity |", "|---|---|---|---|---|---|---|"]
    for r in ds.itertuples():
        lines.append(f"| [{r.source_key}]({r.landing_url}) | {r.title} | {r.provider} | {r.licence} | {r.publication_updated} | {r.reference_period} | {r.granularity} |")
    lines += ["", "## Notes and limitations by dataset", ""]
    for r in ds.itertuples():
        if r.notes:
            lines.append(f"- **{r.source_key}** - {r.notes}")
    lines += ["", "Datasets were downloaded through documented open-data APIs only (CSO PxStat REST API, data.gov.ie CKAN API, "
              "Tailte Eireann open data download); no web pages were scraped."]
    return "\n".join(lines) + "\n"


def main() -> None:
    DOCS_DIR.mkdir(exist_ok=True)
    (DOCS_DIR / "DATA_CATALOGUE.md").write_text(build_markdown(), encoding="utf-8")
    print("wrote docs/DATA_CATALOGUE.md")


if __name__ == "__main__":
    main()
